using System;
using System.Collections;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedRiposteEffect", menuName = "Data/Battle/Effects/Enemy/CorruptedRiposte Effect")]
public class CorruptedRiposteEffect : Effect
{
	[SerializeField]
	private float lightningStartPositionY = 6f;

	[SerializeField]
	private float initialDelay = 0.3f;

	[SerializeField]
	private float delayToSpawnLightningVFX = 0.3f;

	[SerializeField]
	private float delayToPlayDieAfterVFX = 0.2f;

	[SerializeField]
	private float delayToPlaySecondDieAndOn = 0.3f;

	[NonSerialized]
	private GameObject constantVFXGameObjectDuringThunderingRiposte;

	[NonSerialized]
	private bool corruptedRiposteActivated;

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		corruptedRiposteActivated = false;
	}

	public override int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (!corruptedRiposteActivated)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfterAction(CorruptedRiposteSetup(effectOwner));
		}
		CorruptedAnimalActivation component = effectOwner.GetComponent<CorruptedAnimalActivation>();
		for (int i = 0; i < effectAmount; i++)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfterAction(CorruptedRipostedBasicDieActivation(effectOwner, i == 0));
			if (component.IsBoosted)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfterAction(CorruptedRipostedBoostDieActivation(effectOwner));
			}
		}
		if (!corruptedRiposteActivated)
		{
			corruptedRiposteActivated = true;
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAfterAfterAction(CorruptedRipostedEnd());
			ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		}
		return effectAmount;
	}

	private IEnumerator CorruptedRiposteSetup(GameObject effectOwner)
	{
		yield return new WaitForSeconds(initialDelay);
		effectOwner.GetComponent<CorruptedAnimalEffects>().IsEffectActive(this);
		if (IsThirdVFXEnabled())
		{
			constantVFXGameObjectDuringThunderingRiposte = GetThirdVFX();
			constantVFXGameObjectDuringThunderingRiposte.GetComponent<ParticleEmissionController>().SetActive(value: true);
			yield return new WaitForSeconds(delayToSpawnLightningVFX);
		}
	}

	private IEnumerator CorruptedRipostedBasicDieActivation(GameObject effectOwner, bool first)
	{
		if (!first)
		{
			yield return new WaitForSeconds(delayToPlaySecondDieAndOn);
		}
		if (IsSecondVFXEnabled())
		{
			SpawnCorruptedRiposteLightningVFX(effectOwner);
			yield return new WaitForSeconds(delayToPlayDieAfterVFX);
		}
		CorruptedAnimalActivation component = effectOwner.GetComponent<CorruptedAnimalActivation>();
		yield return component.BasicDiceActivation();
	}

	private IEnumerator CorruptedRipostedBoostDieActivation(GameObject effectOwner)
	{
		yield return new WaitForSeconds(delayToPlaySecondDieAndOn);
		if (IsSecondVFXEnabled())
		{
			SpawnCorruptedRiposteLightningVFX(effectOwner);
			yield return new WaitForSeconds(delayToPlayDieAfterVFX);
		}
		CorruptedAnimalActivation component = effectOwner.GetComponent<CorruptedAnimalActivation>();
		yield return component.BoostDiceActivation();
	}

	private void SpawnCorruptedRiposteLightningVFX(GameObject effectOwner)
	{
		Vector2 vector = new Vector2(GetVFXOwnerPosition(effectOwner).x, lightningStartPositionY);
		PlayEffectActivationSFX();
		GetSecondVFX(GetVFXOwnerPosition(effectOwner), 3f).transform.GetChild(0).GetChild(0).position = vector;
	}

	private IEnumerator CorruptedRipostedEnd()
	{
		if (constantVFXGameObjectDuringThunderingRiposte != null)
		{
			yield return new WaitForSeconds(0.2f);
			constantVFXGameObjectDuringThunderingRiposte.GetComponent<ParticleEmissionController>().SetActive(value: false);
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(constantVFXGameObjectDuringThunderingRiposte, 5f);
		}
		corruptedRiposteActivated = false;
	}
}
